SELECT id, customer_id, end_date, status, LEAD(monthly_fee, 1) OVER w_hist AS next_monthly_fee, SUM(monthly_fee) OVER (ORDER BY start_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_monthly_fee, SUM(monthly_fee) OVER w_running AS running_monthly_fee FROM subscriptions WINDOW w_hist AS (PARTITION BY plan ORDER BY end_date, id), w_running AS (PARTITION BY customer_id ORDER BY monthly_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
